node.action:
Send POST request to {{baseUrl}}/auth with Body:
{
 "username": "admin",
 "password": "password123"
}

Send POST request to {{baseUrl}}/booking with Body:
{
 "firstname" : "Marcie",
 "lastname" : "Jimenez",
 "totalprice" : 150,
 "depositpaid" : true,
 "bookingdates" : {
 "checkin" : "2026-01-01",
 "checkout" : "2026-01-10"
 },
 "additionalneeds" : "Breakfast"
}

Send PUT request to {{baseUrl}}/booking/{{bookingId}}
Header: Cookie: token={{token}}
Body:
{
 "firstname": "Marcie",
 "lastname": "Jimenez",
 "totalprice": 200,
 "depositpaid": true,
 "bookingdates": {
 "checkin": "2026-02-01",
 "checkout": "2026-02-05"
 },
 "additionalneeds": "Full Update Test"
}

Send PATCH request to {{baseUrl}}/booking/{{bookingId}}

Header: Cookie: token={{token}}

Body:
{
 "firstname": "Marcie QA",
 "lastname": "Jimenez Master"
}
